import sqlite3
import re
from collections import defaultdict

conn = sqlite3.connect('/root/data/eventlogs.db')
conn.row_factory = sqlite3.Row
cur = conn.cursor()

all_events = []
for r in cur.execute("SELECT * FROM events ORDER BY timestamp ASC, event_id ASC"):
    all_events.append(dict(r))

malicious_guids = {'{b59756a9-b239-5f17-5307-000000000400}'}
malicious_ids = set()

def is_malicious(evt):
    msg = evt['message'] or ''
    if evt['process_guid'] in malicious_guids:
        return True
    for g in malicious_guids:
        if g in msg:
            return True
    if "ca33ee8b-7d2f-4343-83bb-33cd9ad23223" in msg:
        return True
    if any(term in msg for term in ['SQBmACgAJAB', 'SQBGACgAJAB', 'HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Debug', 'HKLM:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Debug', 'CurrentVersion\\Run\\Updater', 'CurrentVersion\\Run\\\\' + 'Updater']):
        return True
    if evt['event_id'] in ('evt-00256', 'evt-00260'):
         return True
    if "10.10.10.5" in msg:
         return True
    return False

for evt in all_events:
    if is_malicious(evt):
        malicious_ids.add(evt['event_id'])

by_group = defaultdict(list)
for e in all_events:
    if e['event_id'] not in malicious_ids:
        by_group[(e['host'], e['event_code'])].append(e)

print(f"Total events: {len(all_events)}, Malicious: {len(malicious_ids)}, Benign: {len(all_events) - len(malicious_ids)}")
for k, evts in sorted(by_group.items()):
    print(f"{k[0]} | Code {k[1]} | Count: {len(evts)}")
    # print unique images/processes
    images = set(e['image'] for e in evts if e['image'])
    print(f"  Images: {list(images)}")
    # if it's PowerShell, or security log with pgustavo, print detailed command lines
    if k[1] in (800, 4103) or any('pgustavo' in (e['message'] or '').lower() for e in evts):
        print("  DETAILS:")
        for e in evts:
            print(f"    {e['event_id']} | {e['message'][:200].replace('\r\n', ' ')}")

